"python -c "
import os

brain_dir = r'C:\Users\tienc\.gemini\antigravity\brain'
large_files = []
total_size = 0

for root, dirs, files in os.walk(brain_dir):
    for f in files:
        fp = os.path.join(root, f)
        try:
            sz = os.path.getsize(fp)
            total_size += sz
            if sz > 15 * 1024 * 1024:
                large_files.append((fp, sz / (1024*1024)))
        except:
            pass

print(f'Total size: {total_size / (1024*1024):.2f} MB')
print(f'Large files (>15MB): {len(large_files)}')
for p, s in large_files:
    print(f'{s:.2f} MB: {p}')
""

